#![cfg(test)]

use super::*;
use groth16_verifier::RiscZeroGroth16Verifier;
use hex_literal::hex;
use soroban_sdk::Env;

const INITIAL_STATE: &[u8] = &hex!("00000000000000000000000000000000000000000000000000000000000675a0d87a8b0faf867d9521ddb155f3c58b9523367444ac5b8822169c06cd71233ee6000000000000000000000000000000000000000000000000000000000006759f7f3d03a51f303b1f1855592276e609c932cc0f91518ca4d959c38685e9f90a69");
const SEAL: &[u8] = &hex!("");
const JOURNAL: [u8; 288] = hex!("");

#[test]
fn verify_a_proof() {
    let env = Env::default();

    let verifier_id = env.register(RiscZeroGroth16Verifier, ());
    let receiver_id = env.register(SignalReceiver, (verifier_id, INITIAL_STATE));

    let client = SignalReceiverClient::new(&env, &receiver_id);

    client.receive(
        &Bytes::from_slice(&env, SEAL),
        &BytesN::<288>::from_array(&env, &JOURNAL),
    );
}
